/* Foresight hi-fi charts. Inline SVG; every value comes from window.FIXTURE (generated by
   design/fixture/*.py, fictional). Chart grammar (tokens.css):
   observed history = solid ink · forecast = solid blue + P10–P90 band · scenario = dashed
   · buffer = dotted · "Today" rule between observed and forecast.
   Two forecast modes:
   - mode "lows" (Home, Landing, Workspace overview): today's balance, then the lowest balance
     before each payday with its likely range. A calm, readable climb that answers "will I stay
     above my buffer?".
   - default (Workspace "Cash flow" tab): weekly P50 joined with the pay-cycle lows, so the
     within-month sawtooth is drawn where it happens. */

const NS = "http://www.w3.org/2000/svg";
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const toDate = (iso) => new Date(iso + "T00:00:00Z");
const shortDate = (iso) => { const d = toDate(iso); return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]}`; };
const fmt = (v, dp = 0) =>
  (v < 0 ? "−£" : "£") + Math.abs(v).toLocaleString("en-GB", { minimumFractionDigits: dp, maximumFractionDigits: dp });
const fmtK = (v) => (v === 0 ? "£0" : `${v < 0 ? "−" : ""}£${Math.abs(v) / 1000}K`);

function el(tag, attrs = {}, parent) {
  const n = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, v);
  if (parent) parent.appendChild(n);
  return n;
}

/** Forecast points for one series. "lows": today + each pay-cycle low. Otherwise weekly P50/P10/P90
    merged with the pay-cycle lows, sorted by date. */
function forecastPoints(name, mode) {
  const F = window.FIXTURE;
  if (mode === "lows") {
    return [
      { date: F.today, value: F.balance, p10: F.balance, p90: F.balance },
      ...(F.cycles[name] || []).map((c) => ({
        date: c.low_date, value: c.low, p10: c.p10, p90: c.p90, low: true, chance: c.chance_below_buffer_pct,
      })),
    ];
  }
  const pts = new Map();
  (F.weekly[name] || []).forEach((w) => pts.set(w.date, { date: w.date, value: w.p50, p10: w.p10, p90: w.p90 }));
  (F.cycles[name] || []).forEach((c) =>
    pts.set(c.low_date, { date: c.low_date, value: c.low, p10: c.p10, p90: c.p90, low: true, chance: c.chance_below_buffer_pct }),
  );
  return [...pts.values()].sort((a, b) => a.date.localeCompare(b.date));
}

function niceScale(min, max) {
  const span = max - min;
  const step = [500, 1000, 2000, 2500, 5000].find((s) => span / s <= 5) || 5000;
  return { lo: Math.floor(min / step) * step, hi: Math.ceil(max / step) * step, step };
}

/**
 * opts: {
 *   history: bool, series: [{ name, label, colorVar, dash?, band?, endLabel? }],
 *   buffer, bufferLabel, height, heightNarrow,
 *   callout?: { series, cycleIndex, title, value },
 *   ariaLabel
 * }
 */
function renderChart(host, opts) {
  const css = getComputedStyle(document.documentElement);
  const color = (v) => css.getPropertyValue(v).trim();
  const F = window.FIXTURE;
  const W = Math.max(280, host.clientWidth);
  const narrow = W < 560;
  const H = narrow ? opts.heightNarrow || 220 : opts.height || 280;
  // Extra headroom when the Observed / Today labels sit above the plot.
  const m = { t: opts.history ? 34 : 22, r: 12, b: 34, l: narrow ? 40 : 48 };

  const series = opts.series.map((s) => ({ ...s, pts: forecastPoints(s.name, opts.mode) }));
  // A scenario is identical to the baseline until its event; draw it only from the point it
  // diverges, so the dashed line never hides the baseline.
  const base = new Map(series[0].pts.map((p) => [p.date, p.value]));
  series.slice(1).forEach((s) => {
    const i = s.pts.findIndex((p) => base.has(p.date) && Math.abs(base.get(p.date) - p.value) > 1);
    if (i > 0) s.pts = s.pts.slice(i - 1);
  });
  const hist = opts.history ? F.history : [];
  const start = toDate(hist.length ? hist[0].date : F.today);
  const end = toDate(series[0].pts[series[0].pts.length - 1].date);
  const values = [
    ...hist.map((h) => h.balance),
    ...series.flatMap((s) => s.pts.flatMap((p) => (s.band ? [p.p10, p.p90] : [p.value]))),
    opts.buffer ?? 0, 0,
  ];
  const ys = niceScale(Math.min(...values), Math.max(...values));
  const x = (iso) => m.l + ((toDate(iso) - start) / (end - start)) * (W - m.l - m.r);
  const y = (v) => m.t + ((ys.hi - v) * (H - m.t - m.b)) / (ys.hi - ys.lo);

  host.innerHTML = "";
  host.style.setProperty("--chart-h", `${H}px`);
  const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, width: W, height: H, role: "img", "aria-label": opts.ariaLabel || "" }, host);
  const grid = el("g", { class: "grid" }, svg), axis = el("g", { class: "axis" }, svg);

  for (let v = ys.lo; v <= ys.hi + 1e-6; v += ys.step) {
    el("line", { x1: m.l, x2: W - m.r, y1: y(v), y2: y(v) }, grid);
    el("text", { x: m.l - 8, y: y(v) + 4, "text-anchor": "end" }, axis).textContent = fmtK(v);
  }
  // Month ticks; at most four on narrow charts. The first tick keeps clear of the y axis.
  const months = [];
  for (let d = new Date(Date.UTC(start.getUTCFullYear(), start.getUTCMonth() + 1, 1)); d <= end; d.setUTCMonth(d.getUTCMonth() + 1)) {
    months.push(new Date(d));
  }
  const every = Math.max(1, Math.ceil(months.length / (narrow ? 4 : 7)));
  months.forEach((d, i) => {
    if (i % every) return;
    const iso = d.toISOString().slice(0, 10), px = x(iso);
    if (px < m.l + 14) return;
    const t = el("text", { x: px, y: H - m.b + 18, "text-anchor": "middle" }, axis);
    t.textContent = MONTHS[d.getUTCMonth()] + (d.getUTCMonth() === 0 ? ` ${String(d.getUTCFullYear()).slice(2)}` : "");
  });

  // Buffer: dotted, labelled inside the plot so it never clips at narrow widths.
  if (opts.buffer != null) {
    el("line", { x1: m.l, x2: W - m.r, y1: y(opts.buffer), y2: y(opts.buffer), stroke: color("--color-data-buffer"), "stroke-width": 1.5, "stroke-dasharray": "2 4", "stroke-linecap": "round" }, svg);
    el("text", { x: W - m.r - 2, y: y(opts.buffer) - 6, "text-anchor": "end", class: "lbl halo" }, svg).textContent = opts.bufferLabel || "Buffer";
  }
  // Paydays: small ticks on the baseline so the within-month pattern has an anchor.
  if (opts.paydays) {
    F.paydays.filter((d) => toDate(d) >= start && toDate(d) <= end).forEach((d) => {
      el("line", { x1: x(d), x2: x(d), y1: H - m.b - 6, y2: H - m.b, stroke: color("--color-status-success"), "stroke-width": 2, "stroke-linecap": "round" }, svg);
    });
  }
  if (ys.lo < 0) el("line", { x1: m.l, x2: W - m.r, y1: y(0), y2: y(0), stroke: color("--color-border-secondary") }, svg);

  // Today rule between observed and forecast.
  if (hist.length) {
    const tx = x(F.today);
    el("line", { x1: tx, x2: tx, y1: m.t - 8, y2: H - m.b, stroke: color("--color-data-today"), "stroke-width": 1, "stroke-dasharray": "3 3" }, svg);
    el("text", { x: tx + 6, y: m.t - 10, class: "lbl" }, svg).textContent = "Today";
    el("text", { x: tx - 6, y: m.t - 10, "text-anchor": "end", class: "lbl faint" }, svg).textContent = "Observed";
  }

  series.forEach((s) => {
    if (!s.band) return;
    const top = s.pts.map((p) => `${x(p.date)},${y(p.p90)}`).join(" ");
    const bot = [...s.pts].reverse().map((p) => `${x(p.date)},${y(p.p10)}`).join(" ");
    el("polygon", { points: `${top} ${bot}`, fill: color(s.dash ? "--color-data-scenario-band" : "--color-data-forecast-band") }, svg);
  });
  if (hist.length) {
    el("polyline", {
      points: [...hist.map((h) => `${x(h.date)},${y(h.balance)}`), `${x(F.today)},${y(F.balance)}`].join(" "),
      fill: "none", stroke: color("--color-data-observed"), "stroke-width": 2, "stroke-linejoin": "round",
    }, svg);
  }
  series.forEach((s) => {
    el("polyline", {
      points: s.pts.map((p) => `${x(p.date)},${y(p.value)}`).join(" "),
      fill: "none", stroke: color(s.colorVar), "stroke-width": 2, "stroke-linejoin": "round", "stroke-linecap": "round",
      ...(s.dash ? { "stroke-dasharray": "7 5" } : {}),
    }, svg);
    s.pts.filter((p) => p.low).forEach((p) => {
      el("circle", { cx: x(p.date), cy: y(p.value), r: 4, fill: color(s.colorVar), stroke: color("--color-bg-secondary"), "stroke-width": 2 }, svg);
      if (opts.buffer != null && p.value < opts.buffer) {
        el("circle", { cx: x(p.date), cy: y(p.value), r: 8, fill: "none", stroke: color("--color-status-error"), "stroke-width": 1.5 }, svg);
      }
    });
    if (s.endLabel && !narrow) {
      const last = s.pts[s.pts.length - 1];
      el("text", { x: x(last.date) - 4, y: y(last.value) - 10, "text-anchor": "end", class: "lbl strong halo" }, svg).textContent = s.endLabel;
    }
  });

  // Callout: kept inside the plot, above the point unless there is no room, never on the axis.
  if (opts.callout && (narrow || opts.compactCallout)) {
    // Narrow charts: a compact haloed value beside the marker instead of a box over the lines.
    const c = opts.callout, p = F.cycles[c.series][c.cycleIndex];
    const cx = x(p.low_date), cy = y(p.low), right = cx < W / 2;
    // Lift the label into the empty upper part of the plot and join it with a leader line.
    const ly = y(ys.lo + (ys.hi - ys.lo) * 0.62);
    el("line", { x1: cx, x2: cx, y1: ly + 6, y2: cy - 9, stroke: color("--color-border-interactive"), "stroke-width": 1, "stroke-dasharray": "2 3" }, svg);
    el("text", { x: cx + (right ? 4 : -4), y: ly, "text-anchor": right ? "start" : "end", class: "lbl strong halo" }, svg)
      .textContent = `${c.value} · ${shortDate(p.low_date)}`;
  } else if (opts.callout) {
    const c = opts.callout, s = series.find((d) => d.name === c.series);
    const p = F.cycles[c.series][c.cycleIndex];
    const cx = x(p.low_date), cy = y(p.low);
    const box = document.createElement("div");
    box.className = "callout";
    box.innerHTML = `<span>${c.title}</span><strong class="num">${c.value}</strong>`;
    host.appendChild(box);
    const bw = box.offsetWidth, bh = box.offsetHeight, gap = 14;
    const above = cy - gap - bh >= m.t;
    const top = above ? cy - gap - bh : Math.min(cy + gap, H - m.b - bh - 4);
    const left = Math.min(Math.max(cx - bw / 2, m.l + 4), W - m.r - bw - 4);
    box.style.left = `${left}px`;
    box.style.top = `${top}px`;
    box.dataset.place = above ? "above" : "below";
    box.style.setProperty("--arrow-x", `${Math.min(Math.max(cx - left, 12), bw - 12)}px`);
    el("line", { x1: cx, x2: cx, y1: above ? top + bh : cy, y2: above ? cy : top, stroke: color(s.colorVar), "stroke-width": 1, "stroke-dasharray": "2 3", opacity: 0.7 }, svg);
  }

  // Hover: crosshair + tooltip on the nearest forecast point (all series share the weekly grid).
  const cross = el("line", { y1: m.t, y2: H - m.b, stroke: color("--color-border-interactive"), "stroke-width": 1, opacity: 0 }, svg);
  const tip = document.createElement("div");
  tip.className = "tip"; tip.setAttribute("role", "status"); tip.setAttribute("aria-live", "polite");
  host.appendChild(tip);
  const hit = el("rect", { x: m.l, y: 0, width: W - m.l - m.r, height: H, fill: "transparent" }, svg);
  const nearest = (pts, t) => pts.reduce((a, b) => (Math.abs(toDate(b.date) - t) < Math.abs(toDate(a.date) - t) ? b : a));
  const show = (px) => {
    const t = new Date(start.getTime() + ((px - m.l) / (W - m.l - m.r)) * (end - start));
    if (hist.length && t < toDate(F.today)) {
      const h = nearest(hist, t);
      cross.setAttribute("x1", x(h.date)); cross.setAttribute("x2", x(h.date));
      tip.innerHTML = `<div>${shortDate(h.date)} · observed</div><strong class="num">${fmt(h.balance)}</strong>`;
    } else {
      const p0 = nearest(series[0].pts, t);
      cross.setAttribute("x1", x(p0.date)); cross.setAttribute("x2", x(p0.date));
      const rows = series.map((s) => {
        const p = nearest(s.pts, toDate(p0.date));
        return `<div>${s.label}: <b class="num">${fmt(p.value)}</b></div>`;
      }).join("");
      const range = p0.p10 === p0.p90 ? "<div>Today’s balance</div>" : `<div>Likely ${fmt(p0.p10)} to ${fmt(p0.p90)}</div>`;
      tip.innerHTML = `<div>${shortDate(p0.date)}${p0.low ? " · lowest before payday" : ""}</div>${rows}${range}`;
    }
    cross.setAttribute("opacity", 1);
    tip.classList.add("show");
    const tw = tip.offsetWidth, cxp = Number(cross.getAttribute("x1"));
    tip.style.left = `${Math.min(Math.max(cxp - tw / 2, 0), W - tw)}px`;
    tip.style.top = `${m.t}px`;
  };
  hit.addEventListener("mousemove", (e) => {
    const r = svg.getBoundingClientRect();
    show(((e.clientX - r.left) / r.width) * W);
  });
  hit.addEventListener("mouseleave", () => { tip.classList.remove("show"); cross.setAttribute("opacity", 0); });
}

/** Horizontal bars (magnitude, one hue). rows: [{ label, value, note }]. */
function renderHBars(host, opts) {
  const css = getComputedStyle(document.documentElement);
  const color = (v) => css.getPropertyValue(v).trim();
  const rows = opts.rows();
  const W = Math.max(260, host.clientWidth);
  const labelW = Math.min(120, W * 0.32), valueW = 72, rowH = 40, barH = 14;
  const H = rows.length * rowH + 4;
  const max = Math.max(...rows.map((r) => r.value));
  host.innerHTML = "";
  const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, width: W, height: H, role: "img", "aria-label": opts.ariaLabel }, host);
  const tip = document.createElement("div");
  tip.className = "tip"; tip.setAttribute("role", "status"); host.appendChild(tip);
  rows.forEach((r, i) => {
    const yMid = i * rowH + rowH / 2;
    const bw = Math.max(4, ((W - labelW - valueW - 12) * r.value) / max);
    el("text", { x: 0, y: yMid + 4, class: "lbl strong" }, svg).textContent = r.label;
    const bar = el("rect", { x: labelW, y: yMid - barH / 2, width: bw, height: barH, rx: 4, fill: color("--color-data-forecast") }, svg);
    el("text", { x: labelW + bw + 8, y: yMid + 4, class: "lbl strong" }, svg).textContent = fmt(r.value, 2);
    const hit = el("rect", { x: 0, y: i * rowH, width: W, height: rowH, fill: "transparent" }, svg);
    hit.addEventListener("mouseenter", () => {
      bar.setAttribute("fill", color("--color-accent-primary-hover"));
      tip.innerHTML = `<div>${r.label}</div><strong class="num">${fmt(r.value, 2)}</strong><div>${r.note}</div>`;
      tip.classList.add("show");
      tip.style.left = `${Math.min(labelW + bw, W - tip.offsetWidth)}px`;
      tip.style.top = `${Math.max(0, yMid - tip.offsetHeight - 10)}px`;
    });
    hit.addEventListener("mouseleave", () => { bar.setAttribute("fill", color("--color-data-forecast")); tip.classList.remove("show"); });
  });
}

/** Weekly columns with a dotted "usual week" reference. weeks: [{ week_start, amount, orders, partial }]. */
function renderColumns(host, opts) {
  const css = getComputedStyle(document.documentElement);
  const color = (v) => css.getPropertyValue(v).trim();
  const weeks = opts.weeks(), ref = opts.reference();
  const W = Math.max(260, host.clientWidth), narrow = W < 520;
  const H = narrow ? 180 : 200;
  const m = { t: 18, r: 8, b: 28, l: 40 };
  // Round ticks (£0 / £50 / £100 …) with at most four steps.
  const top = Math.max(...weeks.map((w) => w.amount), ref);
  const tick = [10, 20, 25, 50, 100, 200].find((t) => Math.ceil(top / t) <= 4) || 250;
  const hi = Math.ceil(top / tick) * tick;
  const y = (v) => m.t + ((hi - v) * (H - m.t - m.b)) / hi;
  const slot = (W - m.l - m.r) / weeks.length, bw = Math.max(6, slot - (narrow ? 4 : 8));
  host.innerHTML = "";
  const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, width: W, height: H, role: "img", "aria-label": opts.ariaLabel }, host);
  const grid = el("g", { class: "grid" }, svg), axis = el("g", { class: "axis" }, svg);
  for (let v = 0; v <= hi + 0.01; v += tick) {
    el("line", { x1: m.l, x2: W - m.r, y1: y(v), y2: y(v) }, grid);
    el("text", { x: m.l - 6, y: y(v) + 4, "text-anchor": "end" }, axis).textContent = `£${Math.round(v)}`;
  }
  const tip = document.createElement("div");
  tip.className = "tip"; tip.setAttribute("role", "status"); host.appendChild(tip);
  weeks.forEach((w, i) => {
    const x0 = m.l + i * slot + (slot - bw) / 2;
    const recent = i >= weeks.length - 4;
    const bar = el("rect", {
      x: x0, y: y(w.amount), width: bw, height: Math.max(1, y(0) - y(w.amount)), rx: 4,
      fill: color(recent ? "--color-data-forecast" : "--color-data-buffer"),
    }, svg);
    if (i % (narrow ? 4 : 2) === 0 || i === weeks.length - 1) {
      el("text", { x: x0 + bw / 2, y: H - 8, "text-anchor": "middle" }, axis).textContent = shortDate(w.week_start);
    }
    const hit = el("rect", { x: m.l + i * slot, y: m.t, width: slot, height: H - m.t - m.b, fill: "transparent" }, svg);
    hit.addEventListener("mouseenter", () => {
      bar.setAttribute("opacity", 0.8);
      tip.innerHTML = `<div>Week of ${shortDate(w.week_start)}${w.partial ? " · so far" : ""}</div><strong class="num">${fmt(w.amount, 2)}</strong><div>${w.orders} orders</div>`;
      tip.classList.add("show");
      tip.style.left = `${Math.min(Math.max(x0 + bw / 2 - tip.offsetWidth / 2, 0), W - tip.offsetWidth)}px`;
      tip.style.top = "0px";
    });
    hit.addEventListener("mouseleave", () => { bar.setAttribute("opacity", 1); tip.classList.remove("show"); });
  });
  el("line", { x1: m.l, x2: W - m.r, y1: y(ref), y2: y(ref), stroke: color("--color-text-secondary"), "stroke-width": 1.5, "stroke-dasharray": "2 4", "stroke-linecap": "round" }, svg);
}

const RENDERERS = { line: renderChart, hbars: renderHBars, columns: renderColumns };

const redrawers = [];

function mountCharts() {
  document.querySelectorAll("[data-chart]").forEach((host) => {
    const opts = window.CHARTS[host.dataset.chart];
    const render = RENDERERS[opts.type || "line"];
    let last = 0;
    const draw = (force) => {
      // Hidden tab panels have no width; draw when they become visible.
      if (host.clientWidth === 0 || (host.clientWidth === last && force !== true)) return;
      last = host.clientWidth;
      render(host, opts);
    };
    draw();
    new ResizeObserver(() => draw()).observe(host);
    redrawers.push(() => draw(true));
  });
}

// Colours are read from the tokens at render time, so a theme change redraws every chart.
window.addEventListener("fs:themechange", () => {
  requestAnimationFrame(() => redrawers.forEach((redraw) => redraw()));
});
window.addEventListener("DOMContentLoaded", mountCharts);
window.FMT = fmt;
